package in.ac.rtu.medicare.desktop;
import in.ac.rtu.medicare.service.AppointmentService; import javax.swing.*; import java.awt.*;
/** Swing reception desk uses the same service validation and JDBC transaction as the web application. */
public final class ReceptionDesk extends JFrame {private final JTextField patient=new JTextField(),doctor=new JTextField(),when=new JTextField("2026-12-01T10:00"),reason=new JTextField();private final JLabel result=new JLabel(" ");public ReceptionDesk(){super("MediCare Reception Desk");setDefaultCloseOperation(EXIT_ON_CLOSE);setLayout(new GridLayout(6,2,8,8));add(new JLabel("Patient user ID"));add(patient);add(new JLabel("Doctor ID"));add(doctor);add(new JLabel("When (yyyy-MM-ddTHH:mm)"));add(when);add(new JLabel("Reason"));add(reason);JButton book=new JButton("Book appointment");book.addActionListener(e->book());add(book);add(result);setSize(500,280);setLocationRelativeTo(null);}private void book(){try{long id=new AppointmentService().book(Long.parseLong(patient.getText()),Long.parseLong(doctor.getText()),when.getText(),reason.getText());result.setText("Booked #"+id);}catch(Exception e){result.setText(e.getMessage());}}public static void main(String[] a){SwingUtilities.invokeLater(()->new ReceptionDesk().setVisible(true));}}
